#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "F".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Farad)
    );
    assert_eq!(
        format!("2.5 {}", "F").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Farad
        ))
    );
    assert_eq!(
        "pF".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Picofarad)
    );
    assert_eq!(
        format!("2.5 {}", "pF").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Picofarad
        ))
    );
    assert_eq!(
        "nF".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Nanofarad)
    );
    assert_eq!(
        format!("2.5 {}", "nF").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Nanofarad
        ))
    );
    assert_eq!(
        "µF".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Microfarad)
    );
    assert_eq!(
        format!("2.5 {}", "µF").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Microfarad
        ))
    );
    assert_eq!(
        "mF".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Millifarad)
    );
    assert_eq!(
        format!("2.5 {}", "mF").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Millifarad
        ))
    );
    assert_eq!(
        "kF".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Kilofarad)
    );
    assert_eq!(
        format!("2.5 {}", "kF").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Kilofarad
        ))
    );
    assert_eq!(
        "MF".parse::<ElectricCapacitanceUnit>(),
        Ok(ElectricCapacitanceUnit::Megafarad)
    );
    assert_eq!(
        format!("2.5 {}", "MF").parse::<ElectricCapacitance>(),
        Ok(ElectricCapacitance::new(
            2.5,
            ElectricCapacitanceUnit::Megafarad
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricCapacitance>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricCapacitance::from_base(6.0);
    let b = ElectricCapacitance::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricCapacitance::<i64>::from_base(7);
    let b = ElectricCapacitance::<i64>::from_base(2);
    assert_eq!(a + b, ElectricCapacitance::from_base(9));
    assert_eq!(a % b, ElectricCapacitance::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricCapacitance<i64>>(),
        ElectricCapacitance::from_base(9)
    );
}
